  async function buildHeroMap(){
    const mount=document.getElementById('heroMapMount');if(!mount)return;
    try{
      const txt=await fetch('/turkey.svg?hero='+Date.now()).then(r=>{if(!r.ok)throw new Error('map');return r.text()});
      mount.innerHTML=txt;
      const svg=mount.querySelector('svg');if(!svg)throw new Error('svg');
      svg.setAttribute('preserveAspectRatio','xMidYMid meet');
      Object.entries(codeToCity).forEach(([code,city])=>{
        const el=svg.querySelector('#'+code);if(!el)return;
        el.dataset.city=city;el.classList.add(pathStatus(city));
      });
    }catch(e){console.error('Hero map:',e)}
  }


