function renderWorkPackage(lang="tr",pkg="WP2"){
  const L=workPackageData[lang]||workPackageData.tr;
  const P=L.packages[pkg]||L.packages.WP2;

  const set=(id,val)=>{const el=document.getElementById(id);if(el)el.textContent=val;};

  document.querySelectorAll("[data-wp-tab]").forEach(btn=>{
    const active=btn.dataset.wpTab===pkg;
    btn.classList.toggle("active",active);
    btn.setAttribute("aria-selected",active?"true":"false");
  });

  set("wpBadge",pkg);
  set("wpTitle",P.title);
  set("wpSubtitle",P.subtitle);

  const cards=document.getElementById("wpCards");
  if(!cards)return;

  /*
    Kart bağlantıları mevcut ana sayfadaki ilgili bölümlere gider.
    Her kart kendi içinde tamamen tıklanabilir; alttaki ayrı bağlantı satırı yoktur.
  */
  const cardLinks={
    tr:{
      WP2:["?wp=WP2#medya","?wp=WP2#medya","?wp=WP2#akademi","?wp=WP2#ciktilar","?wp=WP2#uluslararasi"],
      WP3:["?wp=WP3#akademi","?wp=WP3#iller","?wp=WP3#iller","?wp=WP3#uluslararasi"],
      WP4:["?wp=WP4#network","?wp=WP4#network","?wp=WP4#network"]
    },
    en:{
      WP2:["?wp=WP2#medya","?wp=WP2#medya","?wp=WP2#akademi","?wp=WP2#ciktilar","?wp=WP2#uluslararasi"],
      WP3:["?wp=WP3#akademi","?wp=WP3#iller","?wp=WP3#iller","?wp=WP3#uluslararasi"],
      WP4:["?wp=WP4#network","?wp=WP4#network","?wp=WP4#network"]
    },
    de:{
      WP2:["?wp=WP2#medya","?wp=WP2#medya","?wp=WP2#akademi","?wp=WP2#ciktilar","?wp=WP2#uluslararasi"],
      WP3:["?wp=WP3#akademi","?wp=WP3#iller","?wp=WP3#iller","?wp=WP3#uluslararasi"],
      WP4:["?wp=WP4#network","?wp=WP4#network","?wp=WP4#network"]
    }
  };

  const links=(cardLinks[lang]||cardLinks.tr)[pkg]||[];

  cards.innerHTML=P.cards.map((c,i)=>{
    const [title,desc,status,wide,stat1,stat2,statLabel]=c;

    const rows=wide && desc.includes("|")
      ? `<div class="wp-list">${desc.split("|").map(x=>`<div class="wp-list-row">${x}</div>`).join("")}</div>`
      : `<p>${desc}</p>`;

    const planned=/planned|planlandı|geplant/i.test(status||"");
    const toAdd=/eklenecek|to be added|wird ergänzt/i.test(status||"") && !(pkg==="WP2" && i===4);
    const statusHtml=(status && !(pkg==="WP2" && i===4))
      ? `<span class="wp-status${planned?" planned":""}${toAdd?" to-add":""}">${status.toUpperCase()}</span>`
      : "";

    const statsHtml=stat1&&stat2
      ? `<div class="wp-stats"><b>${stat1}</b><strong>${stat2}</strong><small>${statLabel||""}</small></div>`
      : "";

    const href=links[i]||"#faaliyetler";

    if(pkg==="WP2" && i===4){
      return `<a class="wp-card wp-card-link wp2-summit-card" href="#wp2-zirve-modal" data-open-wp2-summit aria-label="${title}">
        ${statusHtml}<h5>${title}</h5>${rows}${statsHtml}
      </a>`;
    }

    if(pkg==="WP3" && i===0){
      return `<a class="wp-card wp-card-link wp3-program-card" href="#wp3-akran-program" data-open-wp3-akran aria-label="${title}">
        <h5>${title}</h5>
        <p>${desc}</p>
        <div class="wp3-card-meta"><span>10 Ocak 2026</span><span>14 Şubat 2026</span></div>
      </a>`;
    }

    return `<a class="wp-card wp-card-link${wide?" wide":""}" href="${href}" aria-label="${title}">
      ${statusHtml}<h5>${title}</h5>${rows}${statsHtml}
    </a>`;
  }).join("");

  const setWp=(key,val)=>{
    const el=document.querySelector('[data-wp="'+key+'"]');
    if(el)el.textContent=val;
  };

  setWp("eyebrow",L.eyebrow);
  setWp("pageTitle",L.pageTitle);
  setWp("structure",L.structure);
  setWp("shellLead",L.shellLead);
}


function rememberActivityWP(wp){
  try{
    if(["WP2","WP3","WP4"].includes(wp)){
      sessionStorage.setItem("enetcom_activity_wp",wp);
    }
  }catch(e){}
}
function getActivityWP(){
  try{
    const wp=sessionStorage.getItem("enetcom_activity_wp");
    return ["WP2","WP3","WP4"].includes(wp)?wp:null;
  }catch(e){ return null; }
}
function clearActivityWP(){
  try{sessionStorage.removeItem("enetcom_activity_wp");}catch(e){}
}


function updateWpReturnLinks(lang){
  const params=new URLSearchParams(window.location.search);
  const wp=params.get("wp")||getActivityWP();
  const labels={
    tr:"← "+(wp?wp+" Çalışma Paketlerine Dön":"Çalışma Paketlerine Dön"),
    en:"← "+(wp?wp+" Work Packages":"Back to Work Packages"),
    de:"← "+(wp?wp+" Arbeitspakete":"Zurück zu den Arbeitspaketen")
  };
  document.querySelectorAll("[data-wp-return]").forEach(a=>{
    a.textContent=labels[lang]||labels.tr;
    a.href=wp?`?wp=${encodeURIComponent(wp)}#faaliyetler`:"#faaliyetler";
  });
}

function initWorkPackages(){
  document.querySelectorAll("[data-wp-tab]").forEach(btn=>{
    btn.addEventListener("click",()=>{
      renderWorkPackage(document.documentElement.dataset.lang||"tr",btn.dataset.wpTab);
      updateWpReturnLinks(document.documentElement.dataset.lang||"tr");
    });
  });
  const requested=new URLSearchParams(window.location.search).get("wp");
  const initial=["WP2","WP3","WP4"].includes(requested)?requested:"WP2";
  renderWorkPackage(document.documentElement.dataset.lang||"tr",initial);
  updateWpReturnLinks(document.documentElement.dataset.lang||"tr");
}

