    const initialLang=localStorage.getItem('enetcom_lang')||'tr';
    document.documentElement.dataset.lang=initialLang;

    // Keep the Turkish first paint almost work-free. The page is authored in Turkish,
    // so there is no reason to walk the entire DOM before the user sees it.
